     "포트: 공기가 드나드는 구멍. P(압력 입구), A·B(실린더 연결), R·S(배기) 등으로 표시한다.",
     "3/2 밸브: 단동 실린더의 짝. 한 위치에서는 급기→실린더 전진, 다른 위치에서는 배기→스프링 복귀.",
