     "유량조정밸브: 압력 변화에도 유량을 일정하게 유지하는 압력 보상형. 부하가 바뀌어도 속도가 일정하다.",
     "체크밸브(역지밸브): 한 방향으로만 흐르게 한다. 역류 방지용. 스프링 내장으로 열리는 압력(크래킹 압력)이 있다.",
