    "h": "12. 추력·유량·동력 계산 — 숫자 문제 정복",
    "points": [
     "추력: F = p × A. 예) 0.5 MPa 압력, 피스톤 지름 50 mm → A = π×502/4 ≈ 1963 mm2 → F ≈ 0.5 × 1963 ≈ 982 N.",
     "핵심 단위 감각: 1 MPa = 1 N/mm2. 그래서 MPa × mm2 = N이 바로 나온다. 단위 변환 없이 바로 곱하면 된다.",
     "후진(당김) 추력: 로드(피스톤 막대)가 차지한 면적을 뺀다. A후진 = π(D2 - d2)/4. D=피스톤 지름, d=로드 지름.",
     "유량: Q = A × v. 예) A=20 cm2 실린더가 10 cm/s로 움직이면 Q = 200 cm3/s.",
     "실린더 속도: v = Q / A. 같은 유량이면 면적이 작을수록 빨라진다.",
     "유압 동력: P = p × Q. 단위 맞추기: p(MPa) × Q(L/min) ÷ 60 = kW. 예) 14 MPa × 30 L/min ÷ 60 = 7 kW.",
     "시험 포인트: 계산 문제는 단위가 함정이다. mm2↔cm2, L/min↔cm3/s 변환을 먼저 하고 숫자를 대입하자."
    ]
