     "제3각법: 한국·미국 표준. 물체를 제3각(제1상한)에 놓고 투상한다.",
     "배치 암기: \"평면도↓ 정면도 →우측면도\". 정면도를 가운데 두면, 위쪽에 평면도(위에서 본 것), 오른쪽에 우측면도(오른쪽에서 본 것)가 온다.",
