     "교류 실효값 = 최대값 ÷ √2 ≈ 최대값 × 0.707. 가정용 220V는 실효값이다.",
     "코일(L): 전류가 전압보다 90° 늦음. 콘덴서(C): 전류가 전압보다 90° 앞섬. 저항(R): 동상.",
