     "a접점(메이크 접점): 평상시 열려 있다가 입력 ON이면 닫힌다. \"누르면 켜지는\" 기동 버튼에 쓴다.",
     "b접점(브레이크 접점): 평상시 닫혀 있다가 입력 ON이면 열린다. \"누르면 꺼지는\" 정지 버튼·비상정지에 쓴다.",
     "자기유지 회로: 기동 버튼(PB)을 한 번 눌렀다 떼어도 계속 돌게 하는 회로. 출력 릴레이의 a접점을 PB와 병렬로 연결한다. 실기·필기 공통 1순위.",
     "인터록: 정회전과 역회전 접촉기가 동시에 켜지면 전원이 단락된다. 서로의 b접점으로 잠그는 회로가 인터록이다.",
     "타이머: ON 딜레이(켜지고 n초 후 동작), OFF 딜레이, 한시/순시 접점 구분. 카운터: 설정 횟수 도달 시 동작, 다음 사이클을 위해 리셋 조건 필수.",
     "시험 포인트: 자기유지·인터록 회로도는 그림으로 주고 빈칸을 묻는다. a/b접점 기호를 손으로 그려볼 것."
