     "태그(Tag): 화면의 램프·버튼·숫자와 PLC 메모리를 연결하는 변수. \"화면 버튼을 누르면 PLC의 M100이 켜진다\"는 태그 설정 덕분이다.",
     "태그 설정이 틀리면 화면에 엉뚱한 값이 뜨거나 버튼이 안 먹는다. HMI 개발의 핵심이자 실기 감점 1순위.",
     "화면 설계 원칙: 자주 쓰는 것은 크게·앞에, 비상정지는 항상 같은 위치에. 색상은 운전(녹)·정지(적)·경보(황) 관례를 따른다.",
     "HMI와 PLC는 시리얼·이더넷으로 연결한다. 통신 드라이버(프로토콜) 설정이 맞아야 데이터가 표시된다.",
     "시험 포인트: \"태그 = 화면 객체와 PLC 메모리의 연결 고리\" 정의는 그대로 외울 것."
