     "계산 스텝 (예: 192.168.10.0/26): ① 호스트비트 = 6 → 호스트 수 = 64-2 = 62개 ② 서브넷 크기 64씩: .0, .64, .128, .192 ③ 각 동네의 첫 주소=네트워크, 끝 주소=브로드캐스트.",
