     "0:15~1:45 — 설비·센서 설치 및 결선 (1.5h). 브라켓 고정, 결선, 단품 동작 확인까지.",
     "1:45~3:15 — PLC·HMI 프로그램 (1.5h). 수동 동작 먼저, 그 다음 자동 시퀀스, HMI 3화면.",
     "3:15~4:15 — 네트워크·DB·보안 (1h). IP 설정, ping 테스트, DB 적재 확인, 보안 기본 설정.",
