     "예비 0.5h는 막힌 구간용. 어디서든 30분 넘게 막히면 표시해두고 다음으로 넘어간다.",
     "시험 포인트: 시간 배분표를 외워서 시험장에 들어간다. \"지금 몇 시 구간인가\"를 항상 의식할 것."
