     "□ 센서 설치·결선 → 단품 동작 확인 (손·물체로 입력 LED 확인) □ IO-Link 마스터 포트 매핑 확인",
     "□ PLC 프로그램 작성 → 강제 ON/OFF로 입출력 검증 □ 인터록·비상정지 회로 우선 구현",
     "□ HMI 화면 구성: 조작 화면(버튼·램프) · 모니터링 화면(수치·트렌드) · 알람 화면",
     "□ HMI-PLC 통신 설정 (프로토콜·IP·태그) □ 네트워크 결선 → ping 구간별 테스트",
