     "2위: NPN/PNP - 싱크/소스 불일치. 센서는 켜지는데 PLC 입력이 안 들어오면 이걸 의심.",
     "3위: HMI 태그 오기입. 화면 버튼과 PLC 어드레스가 어긋나면 \"분명 프로그램은 맞는데\" 화면이 안 먹는다.",
     "4위: 결선 전 전원 미차단. 모듈·센서를 태우는 지름길. 결선 작업 전에는 무조건 전원 OFF.",
     "5위: 비상정지·인터록 누락. \"돌아가긴 하는데\" 안전 회로가 없으면 대폭 감점.",
     "6위: 한 구간에 매달리기. 40분 넘게 안 풀리면 표시하고 넘어가기. 뒤 구간 점수가 날아간다.",
