     "데이터 타입: 시간은 DATETIME, 측정값은 FLOAT/INT, 상태는 VARCHAR. 타입이 안 맞으면 적재가 실패한다.",
     "적재 확인: 게이트웨이에서 주기적으로 데이터가 들어오는지 SELECT로 본다. 안 쌓이면 연결(계정·IP·포트)→컬럼명 오타→타입 순으로 본다.",
