     "압력(P): 힘을 면적으로 나눈 것. P = F / A. 같은 힘도 좁은 곳에 가하면 압력이 커진다.",
     "단위 줄기: 1 MPa = 10 bar = 약 10.2 kgf/cm2. 이것만 외우면 환산 문제의 80%가 풀린다.",
