     "정의: 압력 = 힘 ÷ 면적. P = F / A. 단위는 파스칼(Pa) = N/m2.",
     "예시: 100N의 힘을 0.01 m2(손바닥)에 가하면 10,000 Pa = 10 kPa다.",
