     "바(bar): 공장 현장 단위. 1 bar = 100 kPa = 100,000 Pa. 타이어 공기압·공압 설비에 쓴다.",
     "메가파스칼(MPa): 1 MPa = 1,000 kPa = 10 bar. 유압·재료 강도에 쓴다.",
     "kgf/cm2: 예전 단위. 1 kgf/cm2 ≈ 98.1 kPa. 10.2 kgf/cm2 ≈ 1 MPa로 외우자.",
     "psi: 미국 단위. 1 psi ≈ 6.9 kPa. 자전거·자동차 타이어에 보인다.",
     "환산 줄기: 1 MPa = 10 bar = 약 10.2 kgf/cm2. 이 한 줄을 손에 익히자."
