     "정의: 유체 동력 P = 압력 p × 유량 Q. 단위는 W(와트).",
     "예시: 10 MPa × 30 L/min이면 동력은 10 × 30 ÷ 60 = 5 kW다. (L/min을 쓴 공식: P(kW) = p(MPa) × Q(L/min) ÷ 60)",
     "같은 동력이라도 고압·소유량(유압) 또는 저압·대유량(공압)으로 만들 수 있다.",
     "효율: 펌프·모터의 손실로 실제 동력은 계산값보다 작다. 여유를 두고 선정한다.",
